from pathlib import Path

TOUCH = Path("../aram-frontend/frontend/touch.go")
TEST = Path("../aram-frontend/frontend/mobile_call_button_test.go")
source = TOUCH.read_text()
old = '\t\t{ID: "soft-left", Control: "soft-left", Label: "L", Bounds: rectAt(actionX, actionY-buttonSize-gap, buttonSize, buttonSize)},\n'
new = old + '\t\t{ID: "send", Control: "send", Label: "CALL", Bounds: rectAt(actionX+buttonSize+gap, actionY-buttonSize-gap, buttonSize, buttonSize)},\n'
if new not in source:
    if source.count(old) != 1:
        raise SystemExit("mobile action-row baseline did not match")
    source = source.replace(old, new, 1)
old_return = '\treturn buttons\n}\n\n// placedTouchBounds converts'
new_return = '\tplaceUnmappedCallButton(buttons, width, height, options, renderScale)\n\treturn buttons\n}\n\n// placedTouchBounds converts'
if new_return not in source:
    if old_return not in source:
        raise SystemExit("mobile touch layout return did not match")
    source = source.replace(old_return, new_return, 1)
helper = "// placeUnmappedCallButton keeps an added CALL key reachable when an existing\n// custom layout occupies its default slot. Never move a saved button or change\n// saved placements; an explicitly placed/hidden CALL key remains authoritative.\nfunc placeUnmappedCallButton(buttons []touchButton, width, height int, options touchLayoutOptions, renderScale float64) {\n\tif _, placed := options.Placements[\"send\"]; placed {\n\t\treturn\n\t}\n\tindex := -1\n\tfor i := range buttons {\n\t\tif buttons[i].ID == \"send\" {\n\t\t\tindex = i\n\t\t\tbreak\n\t\t}\n\t}\n\tif index < 0 {\n\t\treturn\n\t}\n\tpx := func(value int) int { return scaledPixels(value, renderScale) }\n\tbottom := height - px(statusBarHeight)\n\ttop := bottom - touchDeckHeightWithRenderScale(width, height, options, renderScale)\n\tscreen := image.Rect(0, top, width, bottom)\n\tfree := func(bounds image.Rectangle) bool {\n\t\tif !bounds.In(screen) {\n\t\t\treturn false\n\t\t}\n\t\tfor i, other := range buttons {\n\t\t\tif i != index && bounds.Overlaps(other.Bounds) {\n\t\t\t\treturn false\n\t\t\t}\n\t\t}\n\t\treturn true\n\t}\n\tif free(buttons[index].Bounds) {\n\t\treturn\n\t}\n\tsize := buttons[index].Bounds.Dx()\n\tgap := max(1, px(6))\n\tmargin := px(touchDeckPadding)\n\tfor y := bottom-margin-size; y >= top+margin; y -= size+gap {\n\t\tfor x := margin; x+size <= width-margin; x += size+gap {\n\t\t\tcandidate := rectAt(x, y, size, size)\n\t\t\tif free(candidate) {\n\t\t\t\tbuttons[index].Bounds = candidate\n\t\t\t\treturn\n\t\t\t}\n\t\t}\n\t}\n}\n"
if "func placeUnmappedCallButton(" not in source:
    source += "\n" + helper
TOUCH.write_text(source)
TEST.write_text("package frontend\n\nimport (\n\t\"fmt\"\n\t\"image\"\n\t\"testing\"\n)\n\nfunc callButtonForTest(t *testing.T, buttons []touchButton) touchButton {\n\tt.Helper()\n\tfor _, button := range buttons {\n\t\tif button.ID == \"send\" {\n\t\t\tif button.Control != \"send\" || button.Label != \"CALL\" {\n\t\t\t\tt.Fatalf(\"CALL button delivers wrong action: %#v\", button)\n\t\t\t}\n\t\t\treturn button\n\t\t}\n\t}\n\tt.Fatal(\"mobile deck has no CALL button\")\n\treturn touchButton{}\n}\n\nfunc TestMobileCallButtonIsReachableAcrossLayouts(t *testing.T) {\n\tfor _, size := range [][2]int{{393, 851}, {411, 914}, {658, 1536}, {1080, 2280}, {2280, 1080}} {\n\t\tfor _, circular := range []bool{false, true} {\n\t\t\tfor _, keypad := range []bool{false, true} {\n\t\t\t\tt.Run(fmt.Sprintf(\"%dx%d/circular_%t/keypad_%t\", size[0], size[1], circular, keypad), func(t *testing.T) {\n\t\t\t\t\toptions := touchLayoutOptions{Scale: 1.2, Circular: circular, Keypad: keypad}\n\t\t\t\t\tbuttons := touchControlButtonsWithOptions(size[0], size[1], options)\n\t\t\t\t\tcall := callButtonForTest(t, buttons)\n\t\t\t\t\tcenter := call.Bounds.Min.Add(call.Bounds.Size().Div(2))\n\t\t\t\t\tgot, ok := touchButtonAtWithOptions(center.X, center.Y, size[0], size[1], options)\n\t\t\t\t\tif !ok || got.Control != \"send\" {\n\t\t\t\t\t\tt.Fatalf(\"CALL hit resolves to %#v, %t\", got, ok)\n\t\t\t\t\t}\n\t\t\t\t\tfor _, button := range buttons {\n\t\t\t\t\t\tif button.ID != \"send\" && call.Bounds.Overlaps(button.Bounds) {\n\t\t\t\t\t\t\tt.Fatalf(\"CALL overlaps %s\", button.ID)\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t})\n\t\t\t}\n\t\t}\n\t}\n}\n\nfunc TestMobileCallButtonDoesNotInheritHiddenSoftLeft(t *testing.T) {\n\toptions := editorOptions(40, \"soft-left\", \"soft-right\", \"menu\")\n\toptions.Circular = true\n\toptions.Scale = 1.2\n\tbuttons := touchControlButtonsWithOptions(658, 1536, options)\n\tcallButtonForTest(t, buttons)\n\tif !options.Hidden[\"soft-left\"] || options.Hidden[\"send\"] {\n\t\tt.Fatal(\"showing CALL changed the existing hidden-button settings\")\n\t}\n\tif !isTouchButtonID(\"send\") {\n\t\tt.Fatal(\"settings normalization would discard a saved CALL placement\")\n\t}\n}\n\nfunc TestMobileCallButtonAvoidsCustomLayoutWithoutMovingExistingButtons(t *testing.T) {\n\tconst width, height = 658, 1536\n\toptions := editorOptions(40, \"soft-left\", \"soft-right\", \"menu\")\n\toptions.Circular = true\n\toptions.Scale = 1.2\n\tdefaults := touchControlButtonsWithOptions(width, height, options)\n\tcall := callButtonForTest(t, defaults)\n\tcenter := call.Bounds.Min.Add(call.Bounds.Size().Div(2))\n\toptions.Placements = map[string]TouchPlacement{\n\t\t\"back\": normalizedTouchPlacement(center.X, center.Y, width, height),\n\t\tcircularTouchPadID: {X: 0.23, Y: 0.75},\n\t\t\"num1\": {X: 0.28, Y: 0.60},\n\t\t\"num2\": {X: 0.43, Y: 0.60},\n\t\t\"num3\": {X: 0.58, Y: 0.60},\n\t}\n\tcustom := touchControlButtonsWithOptions(width, height, options)\n\tmoved := callButtonForTest(t, custom)\n\tif moved.Bounds == call.Bounds {\n\t\tt.Fatal(\"CALL remained underneath an existing custom button\")\n\t}\n\tfor _, button := range custom {\n\t\tif button.ID == \"send\" {\n\t\t\tcontinue\n\t\t}\n\t\tif moved.Bounds.Overlaps(button.Bounds) {\n\t\t\tt.Fatalf(\"relocated CALL overlaps %s\", button.ID)\n\t\t}\n\t\tif placement, exists := options.Placements[button.ID]; exists {\n\t\t\tsize := touchDeckMetricsFor(width, height, options).scaled\n\t\t\tif button.ID == circularTouchPadID {\n\t\t\t\tsize = size*3 + touchDeckMetricsFor(width, height, options).gap*2\n\t\t\t}\n\t\t\twant := placedTouchBounds(placement, size, width, height)\n\t\t\tif button.Bounds != want {\n\t\t\t\tt.Fatalf(\"existing %s placement changed: %v, want %v\", button.ID, button.Bounds, want)\n\t\t\t}\n\t\t}\n\t}\n}\n\nfunc TestMobileCallButtonCanBeMovedHiddenAndRestored(t *testing.T) {\n\toptions := editorOptions(40)\n\toptions.Placements = map[string]TouchPlacement{\"send\": {X: 0.1, Y: 0.9}}\n\tcall := callButtonForTest(t, touchControlButtonsWithOptions(658, 1536, options))\n\tif !call.Bounds.In(image.Rect(0, 0, 658, 1536-statusBarHeight)) {\n\t\tt.Fatal(\"custom CALL placement left the screen\")\n\t}\n\tcenter := call.Bounds.Min.Add(call.Bounds.Size().Div(2))\n\tif abs(center.X-65) > 2 || abs(center.Y-1382) > 2 {\n\t\tt.Fatalf(\"saved CALL placement was overridden: %v\", center)\n\t}\n\toptions.Hidden = map[string]bool{\"send\": true}\n\tfor _, button := range touchControlButtonsWithOptions(658, 1536, options) {\n\t\tif button.ID == \"send\" {\n\t\t\tt.Fatal(\"hidden CALL still takes input\")\n\t\t}\n\t}\n\ttray := touchEditorTrayButtons(658, 1536, options)\n\tif len(tray) != 1 || tray[0].ID != \"send\" || !tray[0].Hidden {\n\t\tt.Fatal(\"hidden CALL cannot be restored from the editor tray\")\n\t}\n}\n\nfunc TestMobileCallReleasesDirectionBeforeSendAndReleasesSendOnce(t *testing.T) {\n\tfor _, direction := range directionControlOrder {\n\t\trecorder := &inputRecorder{}\n\t\tshell := &Shell{controlState: map[string]bool{direction: true}}\n\t\tshell.queueInputTransitions(recorder, map[string]bool{\"send\": true})\n\t\tshell.queueInputTransitions(recorder, map[string]bool{\"send\": true})\n\t\tshell.queueInputTransitions(recorder, nil)\n\t\twant := []InputEvent{\n\t\t\t{Control: direction, Pressed: false},\n\t\t\t{Control: \"send\", Pressed: true},\n\t\t\t{Control: \"send\", Pressed: false},\n\t\t}\n\t\tif len(recorder.events) != len(want) {\n\t\t\tt.Fatalf(\"CALL input emitted duplicate/missing transitions: %#v\", recorder.events)\n\t\t}\n\t\tfor i, expected := range want {\n\t\t\tif recorder.events[i] != expected {\n\t\t\t\tt.Fatalf(\"CALL transition %d = %#v, want %#v\", i, recorder.events[i], expected)\n\t\t\t}\n\t\t}\n\t\tif len(shell.controlState) != 0 {\n\t\t\tt.Fatal(\"CALL or a direction remained held after release\")\n\t\t}\n\t}\n}\n")
print("patched mobile CALL key, custom-layout collision handling, and input regressions")
